const float V_SUPPLY = 5.0;
const float V_LED = 2.0;
const int ROWS[] = {220, 1000, 10000};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 3; i++) {
    float mA = (V_SUPPLY - V_LED) / ROWS[i] * 1000.0;   // float keeps the decimals: 3.0 / 220 = 0.0136
    Serial.print(ROWS[i]);
    Serial.print(" ohm: ");
    Serial.print(mA, 2);
    Serial.println(" mA");
  }
  // the smallest resistor for 20 mA: R = (V - V_F) / I
  float rMin = (V_SUPPLY - V_LED) / 0.020;
  Serial.print("20 mA needs ");
  Serial.print(rMin, 0);
  Serial.println(" ohm");
}

void loop() {
}

